            continue
        seen.add(key)
        deduped.append(ep)

    eligible = [ep for ep in deduped if is_eligible(ep)]

    # Determine which normalized paths are needed (PLAN + parents).
    plan_norms = set()
    for path, _ in plan:
        plan_norms.add(norm_of[path])

    all_norms = sorted({norm_of[ep[0]] for ep in deduped})

    def has_eligible(norm):
        return any(norm_of[ep[0]] == norm for ep in eligible)

    def has_deduped(norm):
        return any(norm_of[ep[0]] == norm for ep in deduped)

    needed = set()
    if plan:
        needed.update(plan_norms)
        # Parent path resolution: a normalized path p is a parent of endpoint
        # normalized path e if p is a proper prefix of e.
        for e in plan_norms:
            for p in all_norms:
                if p != e and e.startswith(p) and has_eligible(p):
                    needed.add(p)
    else:
        for n in all_norms:
            if has_eligible(n):
                needed.add(n)

    # Special case: parent path whose only endpoints are for excluded roles,
    # included only if it is the sole provider for that parent path and the
    # parent path is needed for inheritance.
    needed_parents = set()
    if plan:
        for e in plan_norms:
            for p in all_norms:
                if p != e and e.startswith(p):
                    needed_parents.add(p)

    selected = []
    for ep in deduped:
        n = norm_of[ep[0]]
        if n not in needed:
            continue
        if is_eligible(ep):
            selected.append(ep)
        elif plan and n in needed_parents and not has_eligible(n):
            # Only endpoints for excluded roles at this path, and this path is
            # needed for inheritance.
            if not any(norm_of[e[0]] == n and is_eligible(e) for e in deduped):
                selected.append(ep)

    # Rule 4: ordering.
    def seg_count(path):
        return len([s for s in path.split("/") if s])

    def sort_key(ep):
        path, method, role, permission = ep
        return (-seg_count(path), method, role, 0 if permission == "ALLOW" else 1)

    selected.sort(key=sort_key)

    # Rule 7: uniqueness by (original path, method, role).
    out_seen = set()
    out_lines = []
    for ep in selected:
        key = (ep[0], ep[1], ep[2])
        if key in out_seen:
            continue
        out_seen.add(key)
        out_lines.append(" ".join(ep))

    output = "\n".join(out_lines) + "\n" if out_lines else "\n"
    with open(OUTPUT_PATH, "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
